-- EGRAPH_CORPUS_CASE_BEGIN source=D:\sqlite-src\test\fallocate.test
-- EGRAPH_CORPUS_SETUP_BEGIN
PRAGMA max_page_count = 100;
PRAGMA page_size = 1024;
PRAGMA auto_vacuum = 1;
CREATE TABLE t1(a, b);
INSERT INTO t1 VALUES(1, zeroblob(1024*900));
INSERT INTO t1 VALUES(2, zeroblob(1024*900));
DELETE FROM t1 WHERE a = 1;
DELETE FROM t1 WHERE a = 2;
PRAGMA freelist_count;
BEGIN;
INSERT INTO t1 VALUES(1, 2);
COMMIT;
PRAGMA page_size = 1024;
PRAGMA journal_mode = WAL;
CREATE TABLE t1(a, b);
INSERT INTO t1 VALUES(1, zeroblob(35*1024));
PRAGMA wal_checkpoint;
DELETE FROM t1;
VACUUM;
PRAGMA wal_checkpoint;
INSERT INTO t1 VALUES(2, randomblob(35*1024));
PRAGMA wal_checkpoint;
INSERT INTO t1 VALUES(3, randomblob(128));
DELETE FROM t1 WHERE a = 2;
VACUUM;
BEGIN;
-- EGRAPH_BASE_QUERY
SELECT count(a) FROM t1;
-- EGRAPH_CORPUS_CASE_END

-- EGRAPH_CORPUS_CASE_BEGIN source=D:\sqlite-src\test\fallocate.test
-- EGRAPH_CORPUS_SETUP_BEGIN
